Arguments: {"cwd":null,"title":"Compute square coordinates","code":"const tabId = 118779795;
const coords = await browserjs(tabId, () => {
  const board = document.querySelector('wc-chess-board');
  const rect = board.getBoundingClientRect();
  const sqWidth = rect.width / 8;
  const sqHeight = rect.height / 8;

  function getSquareCenter(sq) {
    // sq is e.g. "f1"
    const file = sq.charCodeAt(0) - 97; // 0 for 'a', 5 for 'f'
    const rank = parseInt(sq[1]) - 1; // 0 for '1', 7 for '8'
    // White at bottom: rank 0 is at bottom (y = rect.top + (7 - rank + 0.5)*sqHeight)
    // file 0 is at left (x = rect.left + (file + 0.5)*sqWidth)
    const x = rect.left + (file + 0.5) * sqWidth;
    const y = rect.top + (7 - rank + 0.5) * sqHeight;
    return { x: Math.round(x), y: Math.round(y) };
  }

  return {
    f1: getSquareCenter('f1'),
    f8: getSquareCenter('f8'),
    e7: getSquareCenter('e7'),
    e8: getSquareCenter('e8')
  };
});
